def solve(data):
    cutoff = data.get('cutoff', 10**9)
    winners = {}
    for position, event in enumerate(data['events']):
        if event.get('sequence', 0) > cutoff:
            continue
        if 'id' in event:
            identity = ('id', event['id'])
        else:
            identity = ('anonymous', position)
        rank = (event.get('revision', 0), position)
        if identity not in winners or rank > winners[identity][0]:
            winners[identity] = (rank, event)

    balances = {}
    for _, event in winners.values():
        key = f"{event.get('account', 'default')}|{event.get('currency', 'USD')}"
        balances[key] = balances.get(key, 0) + amount(event, data.get('rounding'))
    return {'balances': balances}
